"""Hero, fichas estaduais, tabela das 27 UFs e fontes."""

from __future__ import annotations

from html import escape as esc

from . import alertas as al
from . import mapa as mapa_mod
from .comum import (
    GRUPOS,
    ROTULO,
    barra,
    campo_de,
