def _fmt_calibracao(cal: dict) -> str:
    def g(k, casas=1):
        return num(cal[k], casas) if cal.get(k) is not None else None

    partes = []
    if cal.get("n_pesquisas") and cal.get("n_estados"):
        partes.append(
