.sn-bg-centro-direita { background: var(--c-centro-direita) }
.sn-bg-direita { background: var(--c-direita) }
.sn-bg-indefinido { background: var(--c-indefinido) }
.sn-c-esquerda { border-color: var(--c-esquerda) }
.sn-c-centro-esquerda { border-color: var(--c-centro-esquerda) }
.sn-c-centro { border-color: var(--c-centro) }
.sn-c-centro-direita { border-color: var(--c-centro-direita) }
.sn-c-direita { border-color: var(--c-direita) }
.sn-c-indefinido { border-color: var(--c-indefinido) }

/* Hero */
.scoreboard.sn-score {
  grid-template-columns: repeat(3, minmax(0, 1fr))
}
.sn-score .candidate.sn-card:last-child {
  display: block;
  border-right: 0
}
.sn-card.dir > b { color: #b6d3ff }
.sn-card.cen > b { color: #e6d98f }
.sn-card.esq > b { color: #ffc1b6 }
.sn-card > b { font-size: clamp(44px, 5vw, 70px) }
.sn-card > b small { font-size: 18px; letter-spacing: 0 }
.sn-card > strong { display: block; font-size: 15px; line-height: 1.45 }
@media (max-width: 700px) {
  .scoreboard.sn-score { grid-template-columns: 1fr }
  .scoreboard.sn-score .candidate.sn-card {
    padding: 16px 0;
    border-right: 0;
    border-top: 1px solid #738775;
    display: block
  }
  .scoreboard.sn-score .candidate.sn-card:first-child { border-top: 0 }
  .scoreboard.sn-score .candidate.sn-card > b {
    font-size: 44px;
    letter-spacing: -2px;
    margin: 4px 0
  }
  .scoreboard.sn-score .candidate.sn-card > strong { font-size: 14px }
  .scoreboard.sn-score .candidate.sn-card > p { font-size: 11px; margin-top: 8px }
}

/* Hemiciclo */
.sn-hemi-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 32px;
  margin: 30px 0 10px
}
.sn-hemi-fig { margin: 0; min-width: 0 }
.sn-fig-title {
  font: 600 12px/1.5 var(--mono);
  letter-spacing: 1.2px;
  text-transform: uppercase;
  margin-bottom: 8px
}
.sn-hemi { display: block; width: 100%; height: auto }

